import{c as o,J as r,h as t,k as a}from"./chunks/framework.WgZQdPFo.js";const d=JSON.parse('{"title":"Personal Operations","description":"Ledger for recording significant personal income, dividends, transfers, and major capital expenditures.","frontmatter":{"title":"Personal Operations","description":"Ledger for recording significant personal income, dividends, transfers, and major capital expenditures.","order":20},"headers":[],"relativePath":"docs/spaces/moy-kapital/operations.md","filePath":"docs/spaces/moy-kapital/operations.md"}'),n={name:"docs/spaces/moy-kapital/operations.md"};function s(i,e,l,c,p,g){return r(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="personal-operations" tabindex="-1">Personal Operations <a class="header-anchor" href="#personal-operations" aria-label="Permalink to &quot;Personal Operations&quot;">​</a></h1><p>The <strong>Personal Operations</strong> tab is the primary ledger for significant financial events in the maker&#39;s personal contour. It is designed not for small everyday receipts (which are captured automatically by the mathematical delta), but for recording <strong>major targeted money movements</strong> that shape your overall financial trajectory.</p><hr><h2 id="operations-ledger-philosophy" tabindex="-1">Operations Ledger Philosophy <a class="header-anchor" href="#operations-ledger-philosophy" aria-label="Permalink to &quot;Operations Ledger Philosophy&quot;">​</a></h2><p>OmniCraft ERP respects your time as an artisan. We never ask you to record every cup of coffee or fuel stop manually.</p><p>Only structural transactions belong in this ledger:</p><ul><li><strong>Business Dividends &amp; Withdrawals:</strong> transferring net profits from the workshop&#39;s cash flow into your personal bank account.</li><li><strong>Capital Injections:</strong> personal loans or equity infusions deposited into the workshop cash register to purchase equipment or raw materials.</li><li><strong>External Major Income:</strong> rental real estate proceeds, external consulting honorariums, or vehicle sales.</li><li><strong>Major Capital Expenses:</strong> property acquisitions, medical procedures, home renovations, or automobile purchases.</li><li><strong>Transfers Between Accounts:</strong> currency conversions, funding brokerage accounts, or moving money into hardware crypto vaults.</li></ul><div class="info custom-block"><p class="custom-block-title">Protecting Delta Integrity</p><p>Recording a major windfall (such as selling a personal vehicle) informs the algorithm of the balance jump, ensuring automated workshop expense tracking remains accurate and unskewed.</p></div><hr><h2 id="logging-an-operation" tabindex="-1">Logging an Operation <a class="header-anchor" href="#logging-an-operation" aria-label="Permalink to &quot;Logging an Operation&quot;">​</a></h2><p>To register a transaction, click <strong>&quot;Add Operation&quot;</strong>:</p><ol><li><strong>Operation Type:</strong><ul><li><strong>Income:</strong> personal wealth increase from external sources.</li><li><strong>Expense:</strong> major targeted personal outflow.</li><li><strong>Transfer:</strong> neutral money movement between owned accounts or currency exchanges.</li></ul></li><li><strong>Amount &amp; Currency:</strong> transactional sum and currency denomination.</li><li><strong>From / To Account:</strong> select the originating and receiving accounts.</li><li><strong>Category:</strong> select from built-in articles (&quot;Business Dividends&quot;, &quot;Investments&quot;, &quot;Major Purchases&quot;, &quot;Taxes&quot;, &quot;Family&quot;).</li><li><strong>Date &amp; Time:</strong> timestamp of the payment.</li><li><strong>Notes:</strong> descriptive context (e.g., &quot;Advance payment for bespoke workshop consulting&quot;).</li></ol><hr><h2 id="filtering-and-audit-views" tabindex="-1">Filtering and Audit Views <a class="header-anchor" href="#filtering-and-audit-views" aria-label="Permalink to &quot;Filtering and Audit Views&quot;">​</a></h2><p>Toolbar filters enable quick review:</p><ul><li><strong>Time Horizon:</strong> filter by current month, quarter, year, or custom range.</li><li><strong>Category &amp; Type:</strong> isolate income inflows or major outflows.</li><li><strong>Search:</strong> rapid search by counterparty name or note keywords.</li></ul>',16)])])}const m=o(n,[["render",s]]);export{d as __pageData,m as default};
